create extension if not exists pgcrypto;
create sequence if not exists public.orders_seq start 1;
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null default ('YD-'||lpad(nextval('public.orders_seq')::text,6,'0')),telegram_chat_id bigint,telegram_user_id bigint,status text not null default 'a_rechercher',quantity integer,size text,color text,budget_max text,delivery_city text,whatsapp text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_images(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,telegram_file_id text not null,created_at timestamptz not null default now());
create table if not exists public.order_events(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,from_status text,to_status text,note text,created_at timestamptz not null default now());
create table if not exists public.quotes(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,product_price numeric,shipping_cost numeric,customs_cost numeric,service_fee numeric,delivery_fee numeric,total numeric,currency text default 'XOF',notes text,created_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,method text,amount numeric,status text default 'pending',reference text,paid_at timestamptz);
create table if not exists public.bot_sessions(telegram_chat_id bigint primary key,telegram_user_id bigint,state text not null default 'idle',data jsonb not null default '{}',updated_at timestamptz not null default now());
alter table public.orders enable row level security; alter table public.order_images enable row level security; alter table public.order_events enable row level security; alter table public.quotes enable row level security; alter table public.payments enable row level security; alter table public.bot_sessions enable row level security;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now(); return new; end$$;
drop trigger if exists orders_touch on public.orders; create trigger orders_touch before update on public.orders for each row execute function public.touch_updated_at();